void abort(void);
void exit(int);

long long acc;

void addhi(short a) { acc += (long long)a << 32; }

void subhi(short a) { acc -= (long long)a << 32; }

int main(void) {
  acc = 0xffff00000000ll;
  addhi(1);
  if (acc != 0x1000000000000ll)
    abort();
  subhi(1);
  if (acc != 0xffff00000000ll)
    abort();
  exit(0);
}


